    /**
     * @method
     * @name indodax#fetchDepositsWithdrawals
     * @description fetch history of deposits and withdrawals
     * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#transaction-history-endpoints
     * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#get-withdraw-coin-information-history
     * @param {string} [code] unified currency code for the currency of the deposit/withdrawals, default is undefined
     * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal, default is undefined
     * @param {int} [limit] max number of deposit/withdrawals to return, default is undefined
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a list of [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<List<ccxt.Transaction>> FetchDepositsWithdrawals(string code = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (this.isTapiV2())
        {
            object deposits = ccxt.BaseExchange.FromTransactionList(await this.FetchDeposits(((string)code),ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), parameters));
            object withdrawals = ccxt.BaseExchange.FromTransactionList(await this.FetchWithdrawals(((string)code),ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), parameters));
            List<object> merged = this.arrayConcat(deposits, withdrawals);
            return ccxt.BaseExchange.ToTransactionList(this.filterBySinceLimit(merged, since, limit, "timestamp"));
        }
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        if ((since != null))
        {
            string startTime = this.yyyymmdd(since);
            ((IDictionary<string,object>)request)["start"] = startTime;
            ((IDictionary<string,object>)request)["end"] = this.yyyymmdd(this.milliseconds());
        }
        Dictionary<string, object> response = await this.privatePostTransHistory(this.extend(request, parameters));
        //
        //     {
        //         "success": 1,
        //         "return": {
        //             "withdraw": {
        //                 "idr": [
        //                     {
        //                         "status": "success",
        //                         "type": "coupon",
        //                         "rp": "115205",
        //                         "fee": "500",
        //                         "amount": "114705",
        //                         "submit_time": "1539844166",
        //                         "success_time": "1539844189",
        //                         "withdraw_id": "1783717",
        //                         "tx": "BTC-IDR-RDTVVO2P-ETD0EVAW-VTNZGMIR-HTNTUAPI-84ULM9OI",
        //                         "sender": "boris",
        //                         "used_by": "viginia88"
        //                     },
        //                     ...
        //                 ],
        //                 "btc": [],
        //                 "abyss": [],
        //                 ...
        //             },
        //             "deposit": {
        //                 "idr": [
        //                     {
        //                         "status": "success",
        //                         "type": "duitku",
        //                         "rp": "393000",
        //                         "fee": "5895",
        //                         "amount": "387105",
        //                         "submit_time": "1576555012",
        //                         "success_time": "1576555012",
        //                         "deposit_id": "3395438",
        //                         "tx": "Duitku OVO Settlement"
        //                     },
        //                     ...
        //                 ],
        //                 "btc": [
        //                     {
        //                         "status": "success",
        //                         "btc": "0.00118769",
        //                         "amount": "0.00118769",
        //                         "success_time": "1539529208",
        //                         "deposit_id": "3602369",
        //                         "tx": "c816aeb35a5b42f389970325a32aff69bb6b2126784dcda8f23b9dd9570d6573"
        //                     },
        //                     ...
        //                 ],
        //                 "abyss": [],
        //                 ...
        //             }
        //         }
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "return", new Dictionary<string, object>() {});
        IDictionary<string, object> withdraw = this.safeDict(data, "withdraw", new Dictionary<string, object>() {});
        IDictionary<string, object> deposit = this.safeDict(data, "deposit", new Dictionary<string, object>() {});
        List<object> transactions = new List<object>() {};
        IDictionary<string, object> currency = null;
        if ((code == null))
        {
            List<object> keys = new List<object>(((IDictionary<string,object>)withdraw).Keys);
            for (int i = 0; i < keys.Count; i++)
            {
                object key = keys[i];
                transactions = this.arrayConcat(transactions, getValue(withdraw, key));
            }
            keys = new List<object>(((IDictionary<string,object>)deposit).Keys);
            for (int i = 0; i < keys.Count; i++)
            {
                object key = keys[i];
                transactions = this.arrayConcat(transactions, getValue(deposit, key));
            }
        } else
        {
            currency = this.currency(((string)code));
            List<object> withdraws = this.safeList(withdraw, (currency.ContainsKey("id") ? currency["id"] : null), new List<object>() {});
            List<object> deposits = this.safeList(deposit, (currency.ContainsKey("id") ? currency["id"] : null), new List<object>() {});
            transactions = this.arrayConcat(withdraws, deposits);
        }
        return ccxt.BaseExchange.ToTransactionList(this.parseTransactions(transactions, currency, since, limit));
    }

    /**
     * @method
     * @name indodax#withdraw
     * @description make a withdrawal
     * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#withdraw-coin-endpoints
     * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#withdraw-coin
     * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#withdraw-idr
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {string} tag
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.network] unified network code, used for crypto withdrawals when options.tapiVersion is "2"
     * @param {string} [params.clientOrderId] client request id, only used when options.tapiVersion is "2"
     * @param {string} [params.bankCode] bank code for an IDR withdrawal when options.tapiVersion is "2"
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<ccxt.Transaction> Withdraw(string code, double amount, string address, string tag = null, object parameters = null)
    {
        object tagVar = tag;
        parameters ??= new Dictionary<string, object>();
        if (this.isTapiV2())
        {
            return ccxt.BaseExchange.ToTransaction(await this.sendWithdrawV2(code, amount, address, tagVar, parameters));
        }
        IList<object> tagparametersVariable = (IList<object>)this.handleWithdrawTagAndParams(tagVar, parameters);
        tagVar = ((IList<object>)tagparametersVariable)[0];
        parameters = ((IList<object>)tagparametersVariable)[1];
        this.checkAddress(address);
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> currency = this.currency(((string)code));
        // Custom string you need to provide to identify each withdrawal.
        // Will be passed to callback URL (assigned via website to the API key)
        // so your system can identify the request and confirm it.
        // Alphanumeric, max length 255.
        Int64 requestId = this.milliseconds();
        // Alternatively:
        // let requestId = this.uuid ();
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "currency", (currency.ContainsKey("id") ? currency["id"] : null) },
            { "withdraw_amount", amount },
            { "withdraw_address", address },
            { "request_id", ((object)requestId).ToString() },
        };
        if (((tagVar != null)) && (!isEqual(tagVar, "")))
        {
            ((IDictionary<string,object>)request)["withdraw_memo"] = tagVar;
        }
        Dictionary<string, object> response = await this.privatePostWithdrawCoin(this.extend(request, parameters));
        //
        //     {
        //         "success": 1,
        //         "status": "approved",
        //         "withdraw_currency": "xrp",
        //         "withdraw_address": "rwWr7KUZ3ZFwzgaDGjKBysADByzxvohQ3C",
        //         "withdraw_amount": "10000.00000000",
        //         "fee": "2.00000000",
        //         "amount_after_fee": "9998.00000000",
        //         "submit_time": "1509469200",
        //         "withdraw_id": "xrp-12345",
        //         "txid": "",
        //         "withdraw_memo": "123123"
        //     }
        //
        return ccxt.BaseExchange.ToTransaction(this.parseTransaction(response, currency));
    }

    public override object parseTransaction(object transaction, object currency = null)
    {
        if (((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("coin"))) || ((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("fiatCurrency"))) || ((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("withdrawStatus"))) || ((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("depositStatus"))) || ((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("txType"))))
        {
            return this.parseV2Transaction(transaction, currency);
        }
        //
        // withdraw
        //
        //     {
        //         "success": 1,
        //         "status": "approved",
        //         "withdraw_currency": "xrp",
        //         "withdraw_address": "rwWr7KUZ3ZFwzgaDGjKBysADByzxvohQ3C",
        //         "withdraw_amount": "10000.00000000",
        //         "fee": "2.00000000",
        //         "amount_after_fee": "9998.00000000",
        //         "submit_time": "1509469200",
        //         "withdraw_id": "xrp-12345",
        //         "txid": "",
        //         "withdraw_memo": "123123"
        //     }
        //
        // transHistory
        //
        //     {
        //         "status": "success",
        //         "type": "coupon",
        //         "rp": "115205",
        //         "fee": "500",
        //         "amount": "114705",
        //         "submit_time": "1539844166",
        //         "success_time": "1539844189",
        //         "withdraw_id": "1783717",
        //         "tx": "BTC-IDR-RDTVVO2P-ETD0EVAW-VTNZGMIR-HTNTUAPI-84ULM9OI",
        //         "sender": "boris",
        //         "used_by": "viginia88"
        //     }
        //
        //     {
        //         "status": "success",
        //         "btc": "0.00118769",
        //         "amount": "0.00118769",
        //         "success_time": "1539529208",
        //         "deposit_id": "3602369",
        //         "tx": "c816aeb35a5b42f389970325a32aff69bb6b2126784dcda8f23b9dd9570d6573"
        //     },
        string? status = this.safeString(transaction, "status");
        Int64? timestamp = this.safeTimestamp2(transaction, "success_time", "submit_time");
        string? depositId = this.safeString(transaction, "deposit_id");
        double? feeCost = this.safeNumber(transaction, "fee");
        Dictionary<string, object> fee = null;
        if (!isEqual(feeCost, null))
        {
            fee = new Dictionary<string, object>() {
                { "currency", this.safeCurrencyCode(null, currency) },
                { "cost", feeCost },
                { "rate", null },
            };
        }
        return new Dictionary<string, object>() {
            { "id", this.safeString2(transaction, "withdraw_id", "deposit_id") },
            { "txid", this.safeString2(transaction, "txid", "tx") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "network", null },
            { "addressFrom", null },
            { "address", this.safeString(transaction, "withdraw_address") },
            { "addressTo", null },
            { "amount", this.safeNumberN(transaction, new List<object>() {"amount", "withdraw_amount", "deposit_amount"}) },
            { "type", ((depositId == null)) ? "withdraw" : "deposit" },
            { "currency", this.safeCurrencyCode(null, currency) },
            { "status", this.parseTransactionStatus(status) },
            { "updated", null },
            { "tagFrom", null },
            { "tag", null },
            { "tagTo", null },
            { "comment", this.safeString(transaction, "withdraw_memo") },
            { "internal", null },
            { "fee", fee },
            { "info", transaction },
        };
    }

    public virtual string? parseTransactionStatus(object status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "success", "ok" },
            { "pending", "pending" },
            { "failed", "failed" },
        };
        return this.safeString(statuses, ((string)status), status);
    }

