            { "address", this.safeString(transaction, "address") },
            { "addressTo", null },
            { "amount", this.safeNumber(transaction, "amount") },
            { "type", ((txKind == null)) ? null : txKind },
            { "currency", code },
            { "status", this.parseTransactionStatus(status) },
            { "updated", updated },
            { "tagFrom", null },
            { "tag", this.safeString(transaction, "addressTag") },
            { "tagTo", null },
            { "comment", null },
            { "internal", null },
            { "fee", fee },
            { "info", transaction },
        };
    }

